def solve(phrase):
    stack = []
    for char in phrase:
        if char in "({[":
            stack.append(char)
        elif char in ")}]":
            if not stack:
                return False
            if char == ")" and stack[-1] != "(":
                return False
            if char == "}" and stack[-1] != "{":
                return False
            if char == "]" and stack[-1] != "[":
                return False
            stack.pop()
    return not stack

def solve(phrase):
    stack = []
    for char in phrase:
        if char == '<':
            stack.append(char)
        elif char == '>':
            if stack and stack[-1] == '<':
                stack.pop()
            else:
                return False
        elif char == '(':
            stack.append(char)
        elif char == ')':
            if stack and stack[-1] == '(':
                stack.pop()
            else:
                return False
    return not stack

